body:
The action buttons (toggle, set-default, delete) are functional in the UI but show toast feedback without actually performing backend operations (lines 71-114). While the TODO comments acknowledge this is pending backend support, these non-functional actions could confuse users during testing. Consider either: (1) disabling these buttons with a tooltip explaining they require backend support, or (2) implementing optimistic UI updates with proper state management so the UI reflects the expected behavior even if not persisted.
```suggestion
    // App activation toggling is not yet supported until backend APIs are available.
    toast.info(
      `Toggling ${app.label || app.name} is not yet supported. Backend API integration is pending.`
    );
  }, []);

  const handleSetDefault = useCallback(async (app: any) => {
    // Setting a default app is not yet supported until backend APIs are available.
    toast.info(
      `Setting ${app.label || app.name} as the default app is not yet supported. Backend API integration is pending.`
    );
  }, []);

  const handleDelete = useCallback(async (appToDelete: any) => {
    // Deleting apps is not yet supported until backend APIs are available.
    if (confirmDelete !== appToDelete.name) {
      setConfirmDelete(appToDelete.name);
      return;
    }
    toast.info(
      `Deleting ${appToDelete.label || appToDelete.name} is not yet supported. Backend API integration is pending.`
    );
    setConfirmDelete(null);
  }, [confirmDelete]);

  const handleBulkToggle = useCallback(async (active: boolean) => {
    // Bulk enable/disable is not yet supported until backend APIs are available.
    const actionLabel = active ? 'enable' : 'disable';
    toast.info(
      `Bulk ${actionLabel} for ${selectedIds.size} app(s) is not yet supported. Backend API integration is pending.`
    );
    setSelectedIds(new Set());
  }, [selectedIds]);
```
